import csv
import io

BOM = "\ufeff"


def _advance_quote_state(line: str, in_quotes: bool) -> bool:
    at_field_start = not in_quotes
    index = 0
    while index < len(line):
        char = line[index]
        if in_quotes:
            if char == '"':
                if index + 1 < len(line) and line[index + 1] == '"':
                    index += 2
                    continue
                in_quotes = False
                at_field_start = False
        elif char == '"':
            if at_field_start:
                in_quotes = True
                at_field_start = False
        elif char in ",\r\n":
            at_field_start = True
        elif not char.isspace():
            at_field_start = False
        index += 1
    return in_quotes


def _drop_comment_lines(text: str) -> str:
    kept: list[str] = []
    in_quotes = False
    for line in text.splitlines(keepends=True):
        if not in_quotes and line.startswith("#"):
            in_quotes = False
            continue
        if not line.strip("\r\n"):
            continue
        kept.append(line)
        in_quotes = _advance_quote_state(line, in_quotes)
    return "".join(kept)


def parse_csv(text: str) -> list[list[str]]:
    if text.startswith(BOM):
        text = text[len(BOM) :]
    rows = csv.reader(io.StringIO(_drop_comment_lines(text)))
    return [row for row in rows if row]
